CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_subscriptionproduct]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_subscriptionproduct]
	(
		[apuk_autorenewal],
		[apuk_autorenewalorderdays],
		[apuk_catalogproductid],
		[apuk_catalogproductid_entitytype],
		[apuk_catalogproductidname],
		[apuk_description],
		[apuk_disablelicensemanagement],
		[apuk_disableonlinerenewal],
		[apuk_disableproducturl],
		[apuk_disableusermanagement],
		[apuk_expirywarningdays],
		[apuk_name],
		[apuk_productcode],
		[apuk_producturl],
		[apuk_recentlylapseddays],
		[apuk_regulatedschemetypeid],
		[apuk_regulatedschemetypeid_entitytype],
		[apuk_regulatedschemetypeidname],
		[apuk_section],
		[apuk_subscriptionproductid],
		[apuk_subscriptionproducttype],
		[apuk_unavailabletobuy],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_autorenewal],
		stg.[apuk_autorenewalorderdays],
		stg.[apuk_catalogproductid],
		stg.[apuk_catalogproductid_entitytype],
		stg.[apuk_catalogproductidname],
		stg.[apuk_description],
		stg.[apuk_disablelicensemanagement],
		stg.[apuk_disableonlinerenewal],
		stg.[apuk_disableproducturl],
		stg.[apuk_disableusermanagement],
		stg.[apuk_expirywarningdays],
		stg.[apuk_name],
		stg.[apuk_productcode],
		stg.[apuk_producturl],
		stg.[apuk_recentlylapseddays],
		stg.[apuk_regulatedschemetypeid],
		stg.[apuk_regulatedschemetypeid_entitytype],
		stg.[apuk_regulatedschemetypeidname],
		stg.[apuk_section],
		stg.[apuk_subscriptionproductid],
		stg.[apuk_subscriptionproducttype],
		stg.[apuk_unavailabletobuy],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_subscriptionproduct] stg
		LEFT JOIN [synapse_ce].[apuk_subscriptionproduct] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
